-- Function: public.fn_get_attendance_needs_attention
-- Backup generated on 2026-11-11 09:04:42

CREATE OR REPLACE FUNCTION public.fn_get_attendance_needs_attention(p_tenant_id uuid, p_date date DEFAULT CURRENT_DATE)  RETURNS TABLE(alert_type character varying, icon character varying, title character varying, description text, branch_name character varying, classroom_name character varying, action_text character varying, action_url character varying, severity character varying)  LANGUAGE plpgsql AS $function$ BEGIN     -- 1. Unmarked children in classrooms     RETURN QUERY     WITH room_unmarked AS (         SELECT              b.name AS b_name,             c.name AS c_name,             COUNT(ca.id) AS unmarked_count         FROM public.child_attendance ca         JOIN public.classrooms c ON ca.classroom_id = c.id         JOIN public.branches b ON c.branch_id = b.id         WHERE ca.tenant_id = p_tenant_id           AND ca.attendance_date = p_date           AND ca.status = 'Not marked'         GROUP BY b.name, c.name         HAVING COUNT(ca.id) > 0     )     SELECT          'UnmarkedAttendance'::VARCHAR AS alert_type,         '◷'::VARCHAR AS icon,         'Attendance not completed'::VARCHAR AS title,         (ru.b_name || ' · ' || ru.c_name || ' has ' || ru.unmarked_count || ' children not marked.')::TEXT AS description,         ru.b_name::VARCHAR AS branch_name,         ru.c_name::VARCHAR AS classroom_name,         'Review classroom'::VARCHAR AS action_text,         ('/management/attendance/classrooms/' || ru.c_name || '?branch=' || ru.b_name)::VARCHAR AS action_url,         'amber'::VARCHAR AS severity     FROM room_unmarked ru     LIMIT 5;      -- 2. Missing child checkouts (Checked in / Present, but departure_time IS NULL)     RETURN QUERY     WITH missing_checkouts AS (         SELECT              b.name AS b_name,             c.name AS c_name,             COUNT(ca.id) AS missing_count         FROM public.child_attendance ca         JOIN public.classrooms c ON ca.classroom_id = c.id         JOIN public.branches b ON c.branch_id = b.id         WHERE ca.tenant_id = p_tenant_id           AND ca.attendance_date = p_date           AND ca.status IN ('Present', 'Late')           AND ca.departure_time IS NULL         GROUP BY b.name, c.name         HAVING COUNT(ca.id) > 0     )     SELECT          'MissingCheckout'::VARCHAR AS alert_type,         '↗'::VARCHAR AS icon,         'Child checkout missing'::VARCHAR AS title,         (mc.b_name || ' · ' || mc.c_name || ' has ' || mc.missing_count || ' children checked in without recorded departure.')::TEXT AS description,         mc.b_name::VARCHAR AS branch_name,         mc.c_name::VARCHAR AS classroom_name,         'Review classroom'::VARCHAR AS action_text,         ('/management/attendance/classrooms/' || mc.c_name || '?branch=' || mc.b_name)::VARCHAR AS action_url,         'amber'::VARCHAR AS severity     FROM missing_checkouts mc     LIMIT 5;      -- 3. Teacher staffing review (branches with active classrooms where teacher attendance count < 2 on a weekday)     RETURN QUERY     WITH branch_teachers AS (         SELECT              b.id AS b_id,             b.name AS b_name,             COUNT(ta.id) FILTER (WHERE ta.status IN ('Present', 'Late')) AS present_teachers         FROM public.branches b         LEFT JOIN public.teacher_attendance ta              ON ta.branch_id = b.id              AND ta.attendance_date = p_date              AND ta.tenant_id = p_tenant_id         WHERE b.tenant_id = p_tenant_id           AND b.is_active = true           AND EXISTS (               SELECT 1 FROM public.classrooms c                WHERE c.branch_id = b.id AND c.is_active = true           )         GROUP BY b.id, b.name         HAVING COUNT(ta.id) FILTER (WHERE ta.status IN ('Present', 'Late')) < 2     )     SELECT          'StaffingReview'::VARCHAR AS alert_type,         '♙'::VARCHAR AS icon,         'Teacher coverage needs review'::VARCHAR AS title,         (bt.b_name || ' branch has ' || bt.present_teachers || ' teachers marked present today.')::TEXT AS description,         bt.b_name::VARCHAR AS branch_name,         ''::VARCHAR AS classroom_name,         'Review branch'::VARCHAR AS action_text,         ('/management/attendance/branches/' || bt.b_name)::VARCHAR AS action_url,         'amber'::VARCHAR AS severity     FROM branch_teachers bt     LIMIT 3; END; $function$ ;
